# Generated by KernelGen: https://github.com/flagos-ai/KernelGen
"""gcu400 matmul_bias_activation: relu(matmul(input, weight) + bias).

Dispatch mirrors the mm / addmm / matmuladd hybrid line (single-sourced from
the sibling ops, never re-tuned locally):

- Saturated / long-K segment: composition-reuse the sibling
  ``gcu400/ops/addmm`` op (which delegates to the captured native kernel, near
  1.0x vs torch on this board) followed by the FlagGems ``relu`` op. The
  Triton GEMM structural ceiling (145-165 vs native 276-297 TFLOPS on large
  16-bit shapes, bmm 10-config sweep) makes any local Triton kernel lose this
  segment structurally, so the GEMM body is delegated and only the ReLU
  epilogue stays local. The 16-bit threshold sits one octave above addmm's
  (2^31 vs 2^29 work): the 1024^3 band keeps the fused Triton kernel, which
  beats native-GEMM + separate relu launch on small-mid shapes.
- Everything else: the local fused kernel below - a copy of the tuned Triton
  addmm kernel body (EVEN mask elision, GROUP_M swizzle) with the broadcast
  bias load and the ReLU epilogue fused in, so the op stays a single kernel
  launch on this segment. Tile parameters come from the sibling's
  ``_select_addmm_config`` (single source; a local tile table here would be a
  structural drift source, linalg_matmul precedent).

The upstream KLX sdnn name-hijack quirk (kernel names starting with
``matmul_bias_activation_kernel`` rewritten into the sdnn GEMM fusion, with a
bf16 large-K precision split via SDNN_PRECISE_MIN_K) does not exist on this
backend - the enflame pass chain has no ttsdnnir rewrite, and the baseline
shows fp16 and bf16 large-K latencies identical (i.e. no hardware fusion ever
fired). The split and the second kernel are therefore dropped; large-K bf16
now rides the native delegation and is bit-identical to the torch reference.
"""

import logging

import torch
import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn
from flag_gems.runtime.backend._enflame.gcu400.ops.addmm import _select_addmm_config
from flag_gems.runtime.backend._enflame.gcu400.ops.addmm import addmm as _gcu400_addmm
from flag_gems.runtime.backend._enflame.gcu400.ops.relu import relu as _gcu400_relu
from flag_gems.utils import broadcastable_to, libentry

logger = logging.getLogger(__name__)

_NATIVE_CHAIN_MIN_WORK_2BYTE = 1 << 31
_NATIVE_CHAIN_MIN_WORK_4BYTE = 1 << 29
_NATIVE_CHAIN_LONG_K = 1 << 15


@libentry()
@triton.jit
def matmul_bias_activation_kernel(
    a_ptr,
    b_ptr,
    bias_ptr,
    c_ptr,
    M,
    N,
    K,
    stride_am,
    stride_ak,
    stride_bk,
    stride_bn,
    stride_bias,
    stride_cm,
    stride_cn,
    BLOCK_SIZE_M: tl.constexpr,
    BLOCK_SIZE_N: tl.constexpr,
    BLOCK_SIZE_K: tl.constexpr,
    GROUP_M: tl.constexpr,
    EVEN: tl.constexpr,
):
    pid = tl.program_id(0)
    grid_m = tl.cdiv(M, BLOCK_SIZE_M)
    grid_n = tl.cdiv(N, BLOCK_SIZE_N)

    width = GROUP_M * grid_n
    group_id = pid // width
    group_size = min(grid_m - group_id * GROUP_M, GROUP_M)
    pid_m = group_id * GROUP_M + (pid % group_size)
    pid_n = (pid % width) // group_size

    offs_am = pid_m * BLOCK_SIZE_M + tl.arange(0, BLOCK_SIZE_M)
    offs_bn = pid_n * BLOCK_SIZE_N + tl.arange(0, BLOCK_SIZE_N)
    offs_k = tl.arange(0, BLOCK_SIZE_K)
    a_ptrs = a_ptr + (offs_am[:, None] * stride_am + offs_k[None, :] * stride_ak)
    b_ptrs = b_ptr + (offs_k[:, None] * stride_bk + offs_bn[None, :] * stride_bn)

    accumulator = tl.zeros((BLOCK_SIZE_M, BLOCK_SIZE_N), dtype=tl.float32)
    for k in range(0, tl.cdiv(K, BLOCK_SIZE_K)):
        if EVEN:
            a = tl.load(a_ptrs)
            b = tl.load(b_ptrs)
        else:
            k_remaining = K - k * BLOCK_SIZE_K
            a = tl.load(
                a_ptrs,
                mask=(offs_am[:, None] < M) & (offs_k[None, :] < k_remaining),
                other=0.0,
            )
            b = tl.load(
                b_ptrs,
                mask=(offs_k[:, None] < k_remaining) & (offs_bn[None, :] < N),
                other=0.0,
            )
        accumulator += tl.dot(a, b, allow_tf32=False)
        a_ptrs += BLOCK_SIZE_K * stride_ak
        b_ptrs += BLOCK_SIZE_K * stride_bk

    offs_cm = pid_m * BLOCK_SIZE_M + tl.arange(0, BLOCK_SIZE_M)
    offs_cn = pid_n * BLOCK_SIZE_N + tl.arange(0, BLOCK_SIZE_N)
    c_ptrs = c_ptr + stride_cm * offs_cm[:, None] + stride_cn * offs_cn[None, :]

    if EVEN:
        bias = tl.load(bias_ptr + offs_cn * stride_bias)[None, :]
    else:
        c_mask = (offs_cm[:, None] < M) & (offs_cn[None, :] < N)
        bias = tl.load(bias_ptr + offs_cn * stride_bias, mask=offs_cn < N, other=0.0)[
            None, :
        ]

    accumulator = accumulator + bias

    # Apply ReLU activation
    # Workaround: synthesized zero tensor avoids a rank-0 constant src1
    # (NaN/-Inf edge differs from where-form; finite inputs identical)
    accumulator = tl.maximum(accumulator, accumulator * 0.0)

    c = accumulator.to(c_ptr.dtype.element_ty)
    if EVEN:
        tl.store(c_ptrs, c)
    else:
        c_mask = (offs_cm[:, None] < M) & (offs_cn[None, :] < N)
        tl.store(c_ptrs, c, mask=c_mask)


def _prefer_native_chain(M, N, K, dtype):
    if K >= _NATIVE_CHAIN_LONG_K:
        return True
    work = M * N * K
    if dtype in (torch.float16, torch.bfloat16):
        return work >= _NATIVE_CHAIN_MIN_WORK_2BYTE
    return work >= _NATIVE_CHAIN_MIN_WORK_4BYTE


def matmul_bias_activation(input, weight, bias):
    """
    Fused matmul + bias + ReLU activation.

    Args:
        input: Input tensor of shape (M, K)
        weight: Weight matrix of shape (K, N)
        bias: Bias vector of shape (N,) or (1, N)

    Returns:
        Output tensor of shape (M, N) with ReLU activation applied
    """
    assert input.shape[1] == weight.shape[0], "Incompatible dimensions"
    assert broadcastable_to(
        bias.shape, (input.shape[0], weight.shape[1])
    ), "Incompatible input shape"
    M, K = input.shape
    _, N = weight.shape

    logger.debug("GEMS_ENFLAME MATMUL_BIAS_ACTIVATION")
    if input.stride(0) > 1 and input.stride(1) > 1:
        input = input.contiguous()
    if weight.stride(0) > 1 and weight.stride(1) > 1:
        weight = weight.contiguous()

    # Saturated / long-K segment: relu(addmm(bias, input, weight)) as a
    # composition of the sibling FlagGems ops - the GEMM body inherits the
    # sibling's native delegation (near-native latency), only the epilogue
    # costs the extra relu pass.
    if (
        bias.dtype == input.dtype
        and weight.dtype == input.dtype
        and _prefer_native_chain(M, N, K, input.dtype)
    ):
        gemm_out = _gcu400_addmm(bias, input, weight, beta=1, alpha=1)
        return _gcu400_relu(gemm_out)

    # Small / mid shapes and mixed dtypes: single fused Triton kernel.
    bias_vec = bias.reshape(-1)
    out = torch.empty((M, N), device=input.device, dtype=input.dtype)

    BLOCK_M, BLOCK_N, BLOCK_K, num_warps, num_stages = _select_addmm_config(
        M, N, K, input.dtype
    )
    even = (M % BLOCK_M == 0) and (N % BLOCK_N == 0) and (K % BLOCK_K == 0)

    grid = (triton.cdiv(M, BLOCK_M) * triton.cdiv(N, BLOCK_N),)
    with torch_device_fn.device(input.device):
        matmul_bias_activation_kernel[grid](
            input,
            weight,
            bias_vec,
            out,
            M,
            N,
            K,
            input.stride(0),
            input.stride(1),
            weight.stride(0),
            weight.stride(1),
            bias_vec.stride(0),
            out.stride(0),
            out.stride(1),
            BLOCK_SIZE_M=BLOCK_M,
            BLOCK_SIZE_N=BLOCK_N,
            BLOCK_SIZE_K=BLOCK_K,
            GROUP_M=8,
            EVEN=even,
            num_warps=num_warps,
            num_stages=num_stages,
        )
    return out
